        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("gho_"));
    }

    #[test]
    fn scrub_handles_empty_input() {
        let scrubbed = scrub_for_telemetry("", &HashMap::new());
        assert_eq!(scrubbed, "");
    }

    #[test]
    fn scrub_handles_multiple_secret_types_in_one_input() {
        let mut env = HashMap::new();
        env.insert("DB_PASSWORD".to_string(), "mypassword".to_string());

        let input = "Error: mypassword at /Users/dev/app ghp_abcdefghijklmnopqrstuvwxyz1234567890";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert!(!scrubbed.contains("mypassword"));
        assert!(!scrubbed.contains("/Users/dev"));
        assert!(!scrubbed.contains("ghp_"));
    }

    #[test]
    fn scrub_ignores_empty_env_values() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "".to_string());

        let input = "safe text here";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert_eq!(scrubbed, "safe text here");
    }

    #[test]
    fn scrub_ignores_non_secret_env_keys() {
        let mut env = HashMap::new();
        env.insert("PATH".to_string(), "/usr/bin".to_string());
        env.insert("HOME".to_string(), "/Users/me".to_string());

        let input = "safe text with /usr/bin in it";
        let scrubbed = scrub_for_telemetry(input, &env);
        // PATH is not a secret key, so its value shouldn't be masked by OutputMasker
        // (the regex will still catch /Users/ style paths though)
        assert!(scrubbed.contains("/usr/bin"));
    }

    #[test]
    fn telemetry_consent_display_send() {
        assert_eq!(TelemetryConsent::Send.to_string(), "send");
    }

    #[test]
    fn telemetry_consent_display_no_thanks() {
        assert_eq!(TelemetryConsent::NoThanks.to_string(), "no_thanks");
    }

    #[test]
    fn telemetry_consent_display_always() {
        assert_eq!(TelemetryConsent::Always.to_string(), "always");
    }

    #[test]
    fn telemetry_consent_display_never() {
        assert_eq!(TelemetryConsent::Never.to_string(), "never");
    }

    #[test]
    fn build_report_with_none_exit_code() {
        let report = build_report(
            "test",
            "make build",
            None,
            "some error",
            "shell → retry",
            &HashMap::new(),
        );
        assert_eq!(report.exit_code, None);
        assert_eq!(report.recovery_action, "shell → retry");
    }

    #[test]
    fn build_report_scrubs_command() {
        let mut env = HashMap::new();
        env.insert("SECRET_KEY".to_string(), "hunter2".to_string());

        let report = build_report(
            "deploy",
            "curl -H 'Authorization: hunter2' https://api.example.com",
            Some(1),
            "",
            "retry",
            &env,
        );

        assert!(!report.command_scrubbed.contains("hunter2"));
    }

    #[test]
    fn build_report_includes_platform() {
        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
        let expected_platform = format!("{}-{}", std::env::consts::OS, std::env::consts::ARCH);
        assert_eq!(report.platform, expected_platform);
    }

    #[test]
    fn failure_report_serde_round_trip() {
        let report = FailureReport {
            step_name: "bundler".to_string(),
            command_scrubbed: "bundle install".to_string(),
            exit_code: Some(1),
            error_scrubbed: "gem build error".to_string(),
            recovery_action: "retry".to_string(),
            bivvy_version: "1.0.0".to_string(),
            platform: "macos-aarch64".to_string(),
        };

        let yaml = serde_yaml::to_string(&report).unwrap();
        let deserialized: FailureReport = serde_yaml::from_str(&yaml).unwrap();

        assert_eq!(deserialized.step_name, report.step_name);
        assert_eq!(deserialized.command_scrubbed, report.command_scrubbed);
        assert_eq!(deserialized.exit_code, report.exit_code);
        assert_eq!(deserialized.error_scrubbed, report.error_scrubbed);
        assert_eq!(deserialized.recovery_action, report.recovery_action);
        assert_eq!(deserialized.bivvy_version, report.bivvy_version);
        assert_eq!(deserialized.platform, report.platform);
    }

    #[test]
    fn failure_report_serde_with_none_exit_code() {
        let report = FailureReport {
            step_name: "test".to_string(),
            command_scrubbed: "echo".to_string(),
            exit_code: None,
            error_scrubbed: "".to_string(),
            recovery_action: "skip".to_string(),
            bivvy_version: "1.0.0".to_string(),
            platform: "linux-x86_64".to_string(),
        };

        let yaml = serde_yaml::to_string(&report).unwrap();
        let deserialized: FailureReport = serde_yaml::from_str(&yaml).unwrap();
        assert_eq!(deserialized.exit_code, None);
    }

    #[test]
    fn save_report_to_creates_directory() {
        let temp = tempfile::TempDir::new().unwrap();
        let nested = temp.path().join("deeply").join("nested").join("dir");

        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
        let path = save_report_to(&report, &nested).unwrap();

        assert!(nested.exists());
        assert!(path.exists());
    }

    #[test]
    fn save_report_to_filename_contains_step_name() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report("bundler", "bundle install", Some(1), "", "retry", &HashMap::new());

        let path = save_report_to(&report, temp.path()).unwrap();
        let filename = path.file_name().unwrap().to_str().unwrap();

        assert!(filename.ends_with("-bundler.yml"), "filename was: {}", filename);
    }

    #[test]
    fn save_report_to_writes_valid_yaml() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report(
            "cargo",
            "cargo build",
            Some(101),
            "compilation failed",
            "shell → retry",
            &HashMap::new(),
        );

        let path = save_report_to(&report, temp.path()).unwrap();
        let content = std::fs::read_to_string(&path).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&content).unwrap();

        assert_eq!(loaded.step_name, "cargo");
        assert_eq!(loaded.exit_code, Some(101));
        assert_eq!(loaded.recovery_action, "shell → retry");
    }

